function kd_post($key,$type,$title,$slug,$content,$template=''){
 global $kd;$id=$kd['objects'][$key]??0;if(!$id){$existing=get_page_by_path($slug,OBJECT,$type);if($existing&&get_post_meta($existing->ID,'_kumo_demo_example',true)!==$key)WP_CLI::error('Unowned example collision');$id=$existing?$existing->ID:0;}
 $data=['post_type'=>$type,'post_title'=>$title,'post_name'=>$slug,'post_content'=>$content,'post_status'=>'draft','post_author'=>1,'comment_status'=>str_contains($key,'comments')?'open':'closed','ping_status'=>'closed'];if($id){if(get_post_meta($id,'_kumo_demo_example',true)!==$key)WP_CLI::error('Owner changed');$data['ID']=$id;}$id=$id?wp_update_post(wp_slash($data),true):wp_insert_post(wp_slash($data),true);if(is_wp_error($id))WP_CLI::error($id->get_error_message());update_post_meta($id,'_kumo_demo_example',$key);if($template)update_post_meta($id,'_wp_page_template',$template);if(get_post($id)->post_content!==$content||get_post($id)->post_status!=='draft')WP_CLI::error('Draft readback mismatch');$kd['objects'][$key]=$id;kd_save();return $id;
}
function kd_p($text){return '<!-- wp:paragraph --><p>'.$text.'</p><!-- /wp:paragraph -->';}
function kd_h($text,$level=2){return '<!-- wp:heading '.wp_json_encode(['level'=>$level]).' --><h'.$level.' class="wp-block-heading">'.$text.'</h'.$level.'><!-- /wp:heading -->';}
function kd_block($name,$attrs=[]){return serialize_block(['blockName'=>'core/'.$name,'attrs'=>$attrs,'innerBlocks'=>[],'innerHTML'=>'','innerContent'=>[]]);}
function kd_widget($key,$base,$config){global $kd;$all=get_option('widget_'.$base,[]);$id=$kd['widget_map'][$key]??'';if($id){$at=(int)substr($id,strrpos($id,'-')+1);}else{$at=80;while(isset($all[$at]))++$at;$id=$base.'-'.$at;}$all[$at]=$config;$all['_multiwidget']=1;update_option('widget_'.$base,$all);$kd['widget_map'][$key]=$id;kd_save();return $id;}
