$coreId=kd_post('block-comments','page','Core Comments blocks','comments-blocks',$core,'page-templates/full-width.php');$kd['comment_examples']=[$classic,$coreId];wp_set_post_terms($classic,['Design','WordPress','Publishing'],'post_tag',true);kd_save();
